import * as React from "react";

const NoSelection = (props) => {
  const reactId = React.useId().replace(/:/g, "");
  const patternId = `no-selection-pattern-${reactId}`;
  const imageId = `no-selection-image-${reactId}`;

  return (
    <svg
      width={160}
      height={160}
      viewBox="0 0 160 160"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
      {...props}
    >
      <rect width="160" height="160" fill={`url(#${patternId})`} />
      <defs>
        <pattern
          id={patternId}
          patternContentUnits="objectBoundingBox"
          width="1"
          height="1"
        >
          <use
            xlinkHref={`#${imageId}`}
            transform="translate(-0.160526 -0.148177) scale(0.000410285)"
          />
        </pattern>
        <image
          id={imageId}
          width="3126"
          height="3126"
          preserveAspectRatio="none"
          xlinkHref="data:image/png;base64,"
        />
      </defs>
    </svg>
  );
};

export default NoSelection;
